import sys

def add(*nums):
    return sum(nums)

def mul(*nums):
    result = 1
    for n in nums:
        result *= n
    return result

def avg(*nums):
    if not nums:
        raise ValueError('avg needs at least one number')
    return f'{sum(nums) / len(nums):.2f}'

def power(base, exp):
    return base ** exp

OPS = {'add': add, 'mul': mul, 'avg': avg, 'pow': power}

for line in sys.stdin:
    parts = line.split()
    if not parts:
        continue
    name, *args = parts
    func = OPS.get(name)
    if func is None:
        print(f'Unknown command: {name}')
        continue
    try:
        print(func(*map(int, args)))
    except TypeError:
        print(f'Error: wrong number of arguments for {name}')
    except ValueError as exc:
        print(f'Error: {exc}')

